// App members. Values are logical pixels and independent of the current monitor DPI.
float customEditorWidth=0,projectWidth=260,galleryRatio=.25f,thumbnailSize=180;
bool interactiveResize=false,resizePending=false;Rect galleryDivider;
void fitWorkspace(){leftWidth=projectsOpen?std::clamp(projectWidth,160.f,std::max(160.f,std::min(300.f,width-720))):64.f;float available=std::max(600.f,width-leftWidth-30),minimum=page==0?300.f:390.f,preferred=customEditorWidth>0?customEditorWidth:page==0?380.f:520.f;float editor=std::clamp(preferred,minimum,std::max(minimum,available-300));rightWidth=std::max(280.f,available-editor);}
void rememberWorkspace(){store->settings["_workspace_layout"]={{"editor_width",customEditorWidth},{"project_width",projectWidth},{"gallery_ratio",galleryRatio},{"thumbnail_size",thumbnailSize}};}
void loadWorkspace(){auto layout=store->settings.value("_workspace_layout",json::object());if(!layout.is_object())return;auto number=[&](const char* key,float fallback,float low,float high){auto value=layout.value(key,json());return value.is_number()&&std::isfinite(value.get<float>())?std::clamp(value.get<float>(),low,high):fallback;};customEditorWidth=number("editor_width",0,0,1400);projectWidth=number("project_width",260,160,300);galleryRatio=number("gallery_ratio",.25f,.15f,.65f);thumbnailSize=number("thumbnail_size",180,100,320);}
void applyWorkspace(){fitWorkspace();layoutControls();rememberWorkspace();InvalidateRect(hwnd,nullptr,FALSE);}
void workspaceMenu(){HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING,1,L"설정 패널 너비 (px)");AppendMenuW(menu,MF_STRING,2,L"프로젝트 패널 너비 (px)");AppendMenuW(menu,MF_STRING,3,L"갤러리 너비 (%)");AppendMenuW(menu,MF_STRING,4,L"썸네일 크기 (px)");AppendMenuW(menu,MF_STRING,5,L"창 크기 (너비 x 높이)");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING,6,L"자동 배치로 초기화");POINT cursor;GetCursorPos(&cursor);int choice=TrackPopupMenu(menu,TPM_RETURNCMD,cursor.x,cursor.y,0,hwnd,nullptr);DestroyMenu(menu);if(!choice)return;if(choice==6){customEditorWidth=0;projectWidth=260;galleryRatio=.25f;thumbnailSize=180;}else if(choice==5){auto value=inputBox(hwnd,L"창 크기 · 논리 px (1040x640 이상)",std::to_wstring(int(width))+L"x"+std::to_wstring(int(height)));if(value.empty())return;auto divider=value.find_first_of(L"xX×");if(divider==std::wstring::npos)throw std::runtime_error("너비x높이 형식으로 입력하세요.");size_t usedW=0,usedH=0;int w=std::stoi(value.substr(0,divider),&usedW),h=std::stoi(value.substr(divider+1),&usedH);if(usedW!=divider||usedH!=value.size()-divider-1||w<1040||w>7680||h<640||h>4320)throw std::runtime_error("창 크기: 너비 1040~7680, 높이 640~4320 범위입니다.");RECT r{0,0,LONG(w*dpi),LONG(h*dpi)};AdjustWindowRectExForDpi(&r,GetWindowLongW(hwnd,GWL_STYLE),FALSE,GetWindowLongW(hwnd,GWL_EXSTYLE),UINT(dpi*96));ShowWindow(hwnd,SW_RESTORE);SetWindowPos(hwnd,nullptr,0,0,r.right-r.left,r.bottom-r.top,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);}else{int current=choice==1?int(center().w):choice==2?int(projectWidth):choice==3?int(galleryRatio*100):int(thumbnailSize);auto value=inputBox(hwnd,choice==1?L"설정 패널 너비: 300~1400 px":choice==2?L"프로젝트 너비: 160~300 px":choice==3?L"갤러리 너비: 15~65 %":L"썸네일 크기: 100~320 px",std::to_wstring(current));if(value.empty())return;size_t used=0;int n=std::stoi(value,&used);int low=choice==1?300:choice==2?160:choice==3?15:100,high=choice==1?1400:choice==2?300:choice==3?65:320;if(used!=value.size()||n<low||n>high)throw std::runtime_error("표시된 범위의 정수를 입력하세요.");if(choice==1)customEditorWidth=float(n);else if(choice==2)projectWidth=float(n);else if(choice==3)galleryRatio=n/100.f;else thumbnailSize=float(n);}applyWorkspace();save();}
struct Placement {HWND h;int x,y,w,hgt;};std::map<HWND,RECT> lastPlacement;std::vector<Placement> placements;bool placing=false;
void endPlacements(){placing=false;if(placements.empty())return;auto batch=BeginDeferWindowPos(int(placements.size()));for(auto& p:placements)if(batch)batch=DeferWindowPos(batch,p.h,nullptr,p.x,p.y,p.w,p.hgt,SWP_NOZORDER|SWP_NOACTIVATE|SWP_NOCOPYBITS);bool ok=batch&&EndDeferWindowPos(batch);if(!ok)for(auto& p:placements)SetWindowPos(p.h,nullptr,p.x,p.y,p.w,p.hgt,SWP_NOZORDER|SWP_NOACTIVATE|SWP_NOCOPYBITS);placements.clear();}
void place(HWND h,Rect r,bool combo=false){if(!h)return;RECT rect{int(r.x*dpi),int(r.y*dpi),std::max(1,int(r.w*dpi)),std::max(1,int((combo?240:r.h)*dpi))};auto previous=lastPlacement.find(h);if(previous!=lastPlacement.end()&&EqualRect(&previous->second,&rect))return;lastPlacement[h]=rect;if(placing)placements.push_back({h,rect.left,rect.top,rect.right,rect.bottom});else SetWindowPos(h,nullptr,rect.left,rect.top,rect.right,rect.bottom,SWP_NOZORDER|SWP_NOACTIVATE|SWP_NOCOPYBITS);}
